        dq = deque([0])
        while dq:
            u = dq.popleft()
            hu = h[u]
            r, c = divmod(u, m)
            if r > 0:
                v = u - m
                if not vis[v] and abs(hu - h[v]) <= limit:
                    if v == target:
                        return True
                    vis[v] = 1
                    dq.append(v)
            if r + 1 < n:
                v = u + m
                if not vis[v] and abs(hu - h[v]) <= limit:
                    if v == target:
                        return True
                    vis[v] = 1
                    dq.append(v)
            if c > 0:
                v = u - 1
                if not vis[v] and abs(hu - h[v]) <= limit:
                    if v == target:
                        return True
                    vis[v] = 1
                    dq.append(v)
