                if not vis[v] and abs(hu - h[v]) <= limit:
                    if v == target:
                        return True
                    vis[v] = 1
                    dq.append(v)
        return False

    lo = 0
    hi = max(h) - min(h)
    ans = hi
    while lo <= hi:
