#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

struct Node {
    int len;
    int cnt;
};

Node combine(const Node& a, const Node& b) {
    if (a.len > b.len) return a;
    if (b.len > a.len) return b;
    if (a.len == 0) return {0, 0};
    int c = a.cnt + b.cnt;
    if (c >= MOD) c -= MOD;
    return {a.len, c};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    vector<int> vals = a;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();

    vector<Node> bit(m + 1, {0, 0});
    auto update = [&](int idx, const Node& val) {
        for (; idx <= m; idx += idx & -idx) {
            bit[idx] = combine(bit[idx], val);
        }
    };
    auto query = [&](int idx) {
        Node res{0, 0};
        for (; idx > 0; idx -= idx & -idx) {
            res = combine(res, bit[idx]);
        }
        return res;
    };

    Node ans{0, 0};
    for (int i = 0; i < n; ++i) {
        int r = (int)(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin()) + 1;
        Node prev = query(r - 1);
        Node cur = (prev.len == 0) ? Node{1, 1} : Node{prev.len + 1, prev.cnt};
        update(r, cur);
        ans = combine(ans, cur);
    }

    cout << ans.len << ' ' << ans.cnt << '\n';
    return 0;
}
