def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1 : 1 + n]))

    vals = sorted(set(a))
    m = len(vals)
    bit_len = [0] * (m + 1)
    bit_cnt = [0] * (m + 1)

    ans_len = 0
    ans_cnt = 0

    for x in a:
        idx = bisect.bisect_left(vals, x) + 1
        bl = 0
        bc = 0
        j = idx - 1
        while j > 0:
            lj = bit_len[j]
            if lj > bl:
                bl = lj
                bc = bit_cnt[j]
            elif lj == bl and lj > 0:
                bc = (bc + bit_cnt[j]) % MOD
            j -= j & -j

        cur_len = bl + 1
        cur_cnt = bc if bl > 0 else 1

        j = idx
        while j <= m:
            lj = bit_len[j]
            if cur_len > lj:
                bit_len[j] = cur_len
                bit_cnt[j] = cur_cnt
            elif cur_len == lj:
                bit_cnt[j] = (bit_cnt[j] + cur_cnt) % MOD
            j += j & -j

        if cur_len > ans_len:
            ans_len = cur_len
            ans_cnt = cur_cnt
        elif cur_len == ans_len:
            ans_cnt = (ans_cnt + cur_cnt) % MOD

    sys.stdout.write(f"{ans_len} {ans_cnt}\n")


