    const long long INF = (long long)4e18;
    int stride = k + 1;
    vector<long long> dist((n + 1) * stride, INF);
    using State = pair<long long, int>;
    priority_queue<State, vector<State>, greater<State>> pq;

    dist[1 * stride + 0] = 0;
    pq.push({0, 1 * stride + 0});

    while (!pq.empty()) {
        auto [d, st] = pq.top();
        pq.pop();
        if (d != dist[st]) continue;
        int u = st / stride;
        int used = st % stride;
        if (u == n) {
            cout << d << '\n';
            return 0;
        }
        for (auto [v, w] : adj[u]) {
            int nxt1 = v * stride + used;
            if (d + w < dist[nxt1]) {
                dist[nxt1] = d + w;
                pq.push({d + w, nxt1});
            }
            if (used < k) {
                int nxt2 = v * stride + (used + 1);
                if (d < dist[nxt2]) {
                    dist[nxt2] = d;
                    pq.push({d, nxt2});
                }
            }
        }
    }

    cout << -1 << '\n';
    return 0;
