    for i in range(m):
        eu[i] = int(data[idx])
        ev[i] = int(data[idx + 1])
        ew[i] = int(data[idx + 2])
        idx += 3

    order = sorted(range(m), key=lambda i: ew[i])
    parent = list(range(n + 1))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    adj = [[] for _ in range(n + 1)]
    mst_cost = 0
    taken = 0
    for i in order:
        u = eu[i]
        v = ev[i]
        ru = find(u)
        rv = find(v)
        if ru != rv:
            parent[rv] = ru
            w = ew[i]
            mst_cost += w
            adj[u].append((v, w))
            adj[v].append((u, w))
            taken += 1
            if taken == n - 1:
                break

    logn = n.bit_length()
    depth = [-1] * (n + 1)
    up = [[1] * (n + 1) for _ in range(logn)]
    mx = [[0] * (n + 1) for _ in range(logn)]

    depth[1] = 0
    dq = deque([1])
    while dq:
        u = dq.popleft()
        du = depth[u] + 1
        for v, w in adj[u]:
            if depth[v] == -1:
                depth[v] = du
                up[0][v] = u
                mx[0][v] = w
                dq.append(v)

    for k in range(1, logn):
        up_prev = up[k - 1]
        mx_prev = mx[k - 1]
        up_cur = up[k]
        mx_cur = mx[k]
        for u in range(1, n + 1):
            p = up_prev[u]
            up_cur[u] = up_prev[p]
            a = mx_prev[u]
            b = mx_prev[p]
            mx_cur[u] = a if a > b else b

    out = []
    for qi in range(q):
        eid = int(data[idx + qi]) - 1
        u = eu[eid]
        v = ev[eid]
        res = 0
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        k = 0
        while diff:
            if diff & 1:
                val = mx[k][u]
                if val > res:
                    res = val
                u = up[k][u]
            diff >>= 1
            k += 1
        if u != v:
            for k in range(logn - 1, -1, -1):
                if up[k][u] != up[k][v]:
                    a = mx[k][u]
                    b = mx[k][v]
                    if a > res:
                        res = a
                    if b > res:
                        res = b
                    u = up[k][u]
                    v = up[k][v]
            a = mx[0][u]
            b = mx[0][v]
            if a > res:
                res = a
            if b > res:
                res = b
        out.append(str(mst_cost - res + ew[eid]))

    sys.stdout.write("\n".join(out) + "\n")


