    if c[0] > 0:
        dp[1][c[0]] = 0
    else:
        for j in range(1, m + 1):
            dp[1][j] = p[0][j]

    for i in range(1, n):
        ndp = [[inf] * (m + 1) for _ in range(target_k + 1)]
        lim_k = i + 1 if i + 1 < target_k else target_k
        ci = c[i]
        pi = p[i]

        for k in range(1, lim_k + 1):
            min1 = inf
            min2 = inf
            col1 = -1
            if k > 1:
                prev_row = dp[k - 1]
                for j in range(1, m + 1):
                    val = prev_row[j]
                    if val < min1:
                        min2 = min1
                        min1 = val
                        col1 = j
                    elif val < min2:
                        min2 = val

            cur_row = dp[k]
            out_row = ndp[k]
            if ci > 0:
                best_prev = cur_row[ci]
                if k > 1:
                    diff_seg = min2 if ci == col1 else min1
                    if diff_seg < best_prev:
